import React, { useState } from 'react';
import Sidebar from './Sidebar'; // ඔයාගේ Sidebar ෆයිල් එක

export default function AdminDashboard({ userName, onLogoutClick }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  // මෙතන තමයි ක්ලික් කරන මෙනු එක අනුව පේජ් එක මාරු වෙන්නේ
  const renderContent = () => {
    switch (currentSubPage) {
      case 'Overview':
        return <div style={{ padding: '20px' }}><h2>Dashboard Overview</h2><p>චාට් සහ ස්ටැට්ස් මෙතනට දාන්න.</p></div>;
      case 'Manage Teachers':
        return <div style={{ padding: '20px' }}><h2>Manage Teachers</h2><p>ටීචර්ස්ලා ඇඩ් කරන සහ මැනේජ් කරන තැන.</p></div>;
      case 'Manage Students':
        return <div style={{ padding: '20px' }}><h2>Manage Students</h2><p>ස්ටුඩන්ට්ස්ලා මැනේජ් කරන තැන.</p></div>;
      case 'Manage Classes':
        return <div style={{ padding: '20px' }}><h2>Manage Classes</h2><p>පන්ති මැනේජ් කරන තැන.</p></div>;
      case 'Reports':
        return <div style={{ padding: '20px' }}><h2>Reports</h2><p>රිපෝට්ස් බලන තැන.</p></div>;
      default:
        return <div>Select an option</div>;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden' }}>
      {/* 1. Sidebar එක (Fixed වෙලා තියෙන්නේ) */}
      <Sidebar 
        currentSubPage={currentSubPage} 
        setCurrentSubPage={setCurrentSubPage} 
        onLogoutClick={onLogoutClick} 
      />

      {/* 2. දකුණු පැත්තේ Content එක (Scroll වෙන්නේ මේ කොටස විතරයි) */}
      <div style={{ 
        flex: 1, 
        backgroundColor: '#f8fafc', 
        display: 'flex', 
        flexDirection: 'column' 
      }}>
        {/* Header එක */}
        <header style={{ 
          padding: '20px', 
          backgroundColor: '#fff', 
          borderBottom: '1px solid #e2e8f0',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}>
          <h2 style={{ margin: 0, color: '#1e293b' }}>{currentSubPage}</h2>
          <div style={{ fontWeight: 'bold', color: '#15803d' }}>Welcome, {userName} 👋</div>
        </header>

        {/* Dynamic Content (මෙනු එක අනුව වෙනස් වෙන කොටස) */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '20px' }}>
          {renderContent()}
        </div>
      </div>
    </div>
  );
}
